import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import { parseScenarioJson, checkScenarioAdmission, sharedOutcomeInputs, selectScenarioSnapshot, validateScenarioPreview,
  sharedEvaluationRequest, validateSharedReport, portableSharedReview, sharedRequestBody, runSharedOutcomeTask, SHARED_MAX_BYTES } from "./dfsSharedOutcomes.js";
import { DFS_SHARED_OUTCOMES_COPY as C } from "./dfsToolPresentation.js";

// This receipt is generated by the real Python scoring/bank engine using explicitly
// synthetic events. It exercises UI contracts without claims about model quality.
const fixture = JSON.parse(fs.readFileSync(new URL("../test-fixtures/dfs-shared-data.json", import.meta.url), "utf8"));
const clone = value => structuredClone(value);
function builder() {
  const { context: c, bank } = fixture.engine_inputs;
  return { context: { site: c.site, season: c.season, week: c.week, slateId: c.slate_id },
    pool: clone(fixture.ui_pool), lineups: clone(fixture.built_lineups),
    vegasGames: bank.games.map(g => ({ game_id: g.game_id, home: g.home_team, away: g.away_team, kickoff_at: g.kickoff_at })),
    settings: { objective: "median" }, locked: [], excluded: [], globalExposure: {}, globalGroups: [] };
}
async function selected() {
  const inputs = sharedOutcomeInputs(builder());
  const snapshot = await selectScenarioSnapshot(inputs, fixture.summary, "2026-10-12T12:00:00Z");
  const request = sharedEvaluationRequest(snapshot, fixture.engine_inputs.bank);
  const report = { ...clone(fixture.evaluation), input_snapshot_id: snapshot.input_snapshot_id };
  return { inputs, snapshot, request, report };
}

test("bounded JSON parsing preserves exact data and rejects rights-laundering duplicate fields", () => {
  const parsed = parseScenarioJson(JSON.stringify(fixture.engine_inputs.bank));
  assert.equal(JSON.stringify(parsed), JSON.stringify(fixture.engine_inputs.bank));
  for (const text of ['{"rights":{"hosted_ingestion":false,"hosted_ingestion":true}}', '{"a":1,"\\u0061":2}', '{"__proto__":{}}', '{"constructor":0}'])
    assert.throws(() => parseScenarioJson(text), { message: C.duplicateError });
});
test("malformed, nonfinite and non-JSON whitespace cannot enter a bank", () => {
  for (const text of ['', '[]', '{"n":1e999}', '{"n":NaN}', '{"n":01}', '{"n":1,}', '{"n":1} trailing', '\u00a0{}', '{"n":"\n"}'])
    assert.throws(() => parseScenarioJson(text), { message: C.jsonError });
});
test("byte, nesting and node budgets are enforced before preview", () => {
  assert.throws(() => parseScenarioJson(`{"x":"${"é".repeat(SHARED_MAX_BYTES / 2)}"}`), { message: C.sizeError });
  assert.throws(() => parseScenarioJson(`{"x":${"[".repeat(25)}0${"]".repeat(25)}}`), { message: C.structureError });
  assert.throws(() => parseScenarioJson(`{"x":[${"0,".repeat(250000)}0]}`), { message: C.structureError });
});
test("source rights are checked locally before any remote ingestion", () => {
  const inputs = sharedOutcomeInputs(builder());
  assert.equal(checkScenarioAdmission(fixture.engine_inputs.bank, inputs), fixture.engine_inputs.bank);
  for (const right of ["personal_analysis", "hosted_ingestion", "display"]) for (const denied of [false, null, "true"]) {
    const bank = clone(fixture.engine_inputs.bank); bank.sources[0].rights[right] = denied;
    assert.throws(() => checkScenarioAdmission(bank, inputs), { message: C.rightsError });
  }
  const noSource = clone(fixture.engine_inputs.bank); noSource.sources = [];
  assert.throws(() => checkScenarioAdmission(noSource, inputs), { message: C.rightsError });
});
test("admission binds exact slate, game IDs, teams and kickoff instants with complete pool-game coverage", () => {
  const inputs = sharedOutcomeInputs(builder());
  for (const mutate of [b => b.context.week++, b => b.games[0].game_id = "different", b => b.games[0].kickoff_at = "2099-09-20T18:00:00Z", b => b.games[0].away_team = "NYJ", b => b.games.push(clone(b.games[0])), b => b.games[0] = null]) {
    const bank = clone(fixture.engine_inputs.bank); mutate(bank); assert.throws(() => checkScenarioAdmission(bank, inputs));
  }
  const missing = clone(fixture.engine_inputs.bank); missing.games.pop();
  assert.throws(() => checkScenarioAdmission(missing, inputs), { message: C.coverageError });
  const offset = clone(fixture.engine_inputs.bank); offset.games[0].kickoff_at = "2099-09-20T13:00:00-04:00";
  assert.equal(checkScenarioAdmission(offset, inputs), offset);
});
test("missing exact pool game identity is gated rather than replaced with an all-week game", () => {
  const b = builder(); delete b.pool[0].game_id;
  assert.throws(() => sharedOutcomeInputs(b), { message: C.gameError });
  const wrong = builder(); wrong.vegasGames[0].game_id = "other-week";
  assert.throws(() => sharedOutcomeInputs(wrong), { message: C.gameError });
  const unknown = builder(); unknown.vegasGames[0].kickoff_at = "unknown";
  assert.throws(() => sharedOutcomeInputs(unknown), { message: C.gameError });
  for (const time of ["2099-09-20T17:00:00", "2099-02-30T17:00:00Z", "2099-09-20T24:00:00Z"]) {
    const naive = builder(); naive.vegasGames[0].kickoff_at = time;
    assert.throws(() => sharedOutcomeInputs(naive), { message: C.gameError });
    const bank = clone(fixture.engine_inputs.bank); bank.games[0].kickoff_at = time;
    assert.throws(() => checkScenarioAdmission(bank, sharedOutcomeInputs(builder())), { message: C.gameError });
  }
});
test("explicit empirical event scoring needs no projected means or marginal quantiles", () => {
  const b = builder(); for (const p of b.pool) for (const key of ["Projected Points", "Low (P10)", "High (P90)"]) delete p[key];
  const inputs = sharedOutcomeInputs(b);
  assert.equal(inputs.pool.length, fixture.ui_pool.length); assert.equal(inputs.lineups.length, 2);
  assert.deepEqual(inputs.lineups.map(l => l.lineup_id), ["current:0", "current:1"]);
});
test("legal roster checks reject duplicate IDs, wrong positions, salary overflow and one-game Classic lineups", () => {
  for (const mutate of [b => b.lineups[0].lineup[0] = b.lineups[0].lineup[1], b => b.pool[0].salary = 50000,
    b => b.lineups[0].lineup[0].position = "TE", b => b.pool.find(p => p.player_id === "kc-te").Position = "WR"]) {
    const b = builder(); mutate(b); assert.throws(() => sharedOutcomeInputs(b), { message: C.rosterError });
  }
  const oneGame = builder(); const te = oneGame.pool.find(p => p.player_id === "kc-te");
  Object.assign(te, { game_id: "buf-mia", Team: "MIA", Opponent: "BUF" });
  for (const lineup of oneGame.lineups) Object.assign(lineup.lineup.find(p => p.player_id === "kc-te"), { team: "MIA" });
  assert.throws(() => sharedOutcomeInputs(oneGame), { message: C.rosterError });
});
test("collection selection rejects mixed slates and scoring-equivalent reordered duplicates", () => {
  const b = builder(); b.portfolio = [{ label: "Saved", context: b.context, lineups: b.lineups }];
  assert.deepEqual(sharedOutcomeInputs(b, "collection").lineups.map(l => l.lineup_id), ["collection:0", "collection:1"]);
  b.portfolio[0].context = { ...b.context, week: 6 };
  assert.throws(() => sharedOutcomeInputs(b, "collection"), { message: C.collectionContextError });
  const duplicated = builder(); duplicated.lineups[1] = { lineup: [...duplicated.lineups[0].lineup].reverse() };
  assert.throws(() => sharedOutcomeInputs(duplicated), { message: C.duplicateLineups });
});
test("selected snapshots detach names, rosters and controls and change identity on changed controls", async () => {
  const b = builder(), inputs = sharedOutcomeInputs(b);
  const first = await selectScenarioSnapshot(inputs, fixture.summary, "2026-10-12T12:00:00Z");
  b.pool[0].Player = "Changed"; b.lineups[0].lineup.reverse(); inputs.controls.settings.objective = "floor";
  assert.notEqual(first.player_labels[b.pool[0].player_id], "Changed");
  assert.equal(first.controls.settings.objective, "median"); assert.equal(Object.isFrozen(first.lineups[0].player_ids), true);
  const changed = await selectScenarioSnapshot(inputs, fixture.summary, "2026-10-12T12:00:00Z");
  assert.notEqual(first.input_snapshot_id, changed.input_snapshot_id);
});
test("API envelope carries only exact engine inputs and bounded controls", async () => {
  const { snapshot, request } = await selected();
  assert.deepEqual(Object.keys(request).sort(), ["bank", "bank_id", "context", "draw_count", "input_snapshot_id", "lineups", "pool", "seed"]);
  assert.equal(request.input_snapshot_id, snapshot.input_snapshot_id);
  assert.equal(JSON.parse(sharedRequestBody(request)).bank_id, fixture.summary.content_id);
  for (const seed of [-1, .5, 2 ** 31, NaN]) assert.throws(() => sharedEvaluationRequest(snapshot, request.bank, seed), { message: C.settingsError });
  assert.throws(() => sharedEvaluationRequest(snapshot, request.bank, 0, 33), { message: C.settingsError });
  assert.throws(() => sharedEvaluationRequest({ ...snapshot, lineups: [] }, request.bank), { message: C.buildFirst });
  assert.throws(() => sharedRequestBody({ n: Infinity }), { message: C.jsonError });
  assert.throws(() => sharedRequestBody({ text: "x".repeat(SHARED_MAX_BYTES) }), { message: C.sizeError });
});
test("preview response cannot silently promote calibration or use different pool/context/scoring", () => {
  const inputs = sharedOutcomeInputs(builder()); assert.equal(validateScenarioPreview(fixture.summary, inputs), fixture.summary);
  for (const mutate of [p => p.capabilities.calibrated_marginals = true, p => p.capabilities.forward_forecast = true,
    p => p.counts.pool_players++, p => p.counts.games++, p => p.scoring_version = "other", p => p.context.week++, p => p.content_id = "bad",
    p => p.warnings = [{ invalid: true }], p => p.sources[0].provider = {}, p => p.evidence_scope = {}, p => p.scoring_source.uri = {}]) {
    const preview = clone(fixture.summary); mutate(preview); assert.throws(() => validateScenarioPreview(preview, inputs), { message: C.responseError });
  }
});
test("actual engine fixture accepts exact frozen finalists and preserves its nonzero paired result", async () => {
  const { request, report } = await selected();
  assert.equal(validateSharedReport(report, request), report);
  assert.equal(report.lineups[1].paired_delta_mean_vs_first, -3.703125);
  assert.equal(report.capabilities.calibrated_joint_tail, false);
});
test("response rejects stale identity, wrong rosters, repeated RNG domains and lost common draws", async () => {
  const { request, report } = await selected();
  for (const mutate of [r => r.input_snapshot_id = "old", r => r.bank_id = "0".repeat(64), r => r.lineups[0].player_ids[0] = "unknown",
    r => r.lineups[1].lineup_id = r.lineups[0].lineup_id, r => r.stream_manifest.streams.evaluation = r.stream_manifest.streams.selection,
    r => r.stream_manifest.common_draws_across_lineups = false, r => r.stream_manifest.selected_purpose = "selection", r => r.draw_count++,
    r => r.audit.conservation_passed = false, r => r.audit.pool_players_covered--, r => r.scoring_version = "other", r => r.warnings = [{ invalid: true }]]) {
    const bad = clone(report); mutate(bad); assert.throws(() => validateSharedReport(bad, request), { message: C.responseError });
  }
});
test("every exported distribution statistic is finite, ordered and compatible with disjoint counts", async () => {
  const { request, report } = await selected();
  for (const mutate of [r => r.lineups[0].p10 = r.lineups[0].p90 + 1, r => r.players[0].mean = Infinity,
    r => r.players[0].zero_fraction = 2, r => Object.assign(r.players[0], { zero_fraction: 1, negative_fraction: 1 }),
    r => r.lineups[0].paired_delta_mean_vs_first = "bad", r => r.lineups[0].paired_delta_p10_vs_first = "bad",
    r => r.lineups[0].paired_better_fraction_vs_first = 2, r => r.players[0] = null, r => r.lineups[0] = null]) {
    const bad = clone(report); mutate(bad); assert.throws(() => validateSharedReport(bad, request), { message: C.responseError });
  }
});
test("download omits raw bank, events and observations while retaining computed results and permission receipts", async () => {
  const { snapshot, report } = await selected(); const preview = clone(fixture.summary);
  preview.sources[0].rights.redistribution = false;
  const archive = portableSharedReview(snapshot, preview, report), text = JSON.stringify(archive);
  assert.equal(archive.report.lineups[1].paired_delta_mean_vs_first, -3.703125);
  assert.equal(archive.scenario_reference.sources[0].rights.redistribution, false);
  assert.equal(/"events"|"profiles"\s*:|"shared_state"|"player_scores"|"route_observations"/.test(text), false);
  assert.equal(archive.scenario_reference.content_id, fixture.summary.content_id);
});
test("cancelling a background operation terminates it and ignores its late success", async () => {
  const original = globalThis.Worker; let worker;
  globalThis.Worker = class { constructor() { worker = this; } postMessage() {} terminate() { this.terminated = true; } };
  try {
    const controller = new AbortController(), pending = runSharedOutcomeTask("read", { text: "{}" }, controller.signal);
    controller.abort(); await assert.rejects(pending, { name: "AbortError", message: C.cancelled });
    assert.equal(worker.terminated, true); worker.onmessage({ data: { ok: true, value: "late" } });
    const missing = new AbortController(); missing.abort(); await assert.rejects(runSharedOutcomeTask("read", {}, missing.signal), { name: "AbortError" });
  } finally { globalThis.Worker = original; }
});
